clientes   = pedidos.map { |p| p[:cliente] }.uniq                      # ["ana", "bia"]
por_cliente = pedidos.group_by { |p| p[:cliente] }
                     .transform_values { |ps| ps.sum { |p| p[:valor] } }
nomes = clientes.map(&:capitalize)                                     # ["Ana", "Bia"]

class Versao
  include Comparable
  attr_reader :partes

  def initialize(texto)
    @partes = texto.split(".").map(&:to_i)
  end

  def <=>(outra)
    partes <=> outra.partes
  end

  def to_s = partes.join(".")
end

Versao.new("1.10.0") > Versao.new("1.9.3")   # true
["2.0", "1.10", "1.9"].map { Versao.new(_1) }.max.to_s  # "2.0"
